'use client';
import {useEffect,useState} from 'react';
import {BUSINESS_CATEGORIES,BUSINESS_STATUSES,ManagedBusiness,VERIFICATION_METHODS} from '@/lib/business-shared';
import {request,jsonBody} from '@/lib/client';
import {ErrorBox,Loading} from './city-ui';
import {SafeDate} from './safe-format';
type ReviewBusiness=ManagedBusiness&{user:{name:string;email:string}};
export default function BusinessModeration(){
 const [items,setItems]=useState<ReviewBusiness[]>([]),[status,setStatus]=useState('PENDING'),[page,setPage]=useState(1),[hasNext,setHasNext]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState('');
 async function load(){setLoading(true);setError('');try{const d=await request(`/api/platform/businesses?status=${status}&page=${page}`);setItems(d.items);setHasNext(d.hasNext);}catch(e){console.error(e);setError(e instanceof Error?e.message:'İnceleme listesi yüklenemedi.');}finally{setLoading(false);}}
 useEffect(()=>{void load();},[status,page]);
 return <div className="space-y-6"><div><p className="eyebrow text-primary mb-2">AYRI YETKİ · KAYITLI İNCELEME</p><h1 className="page-title">İşletme yayın yönetimi</h1><p className="text-sm text-muted-foreground mt-2">Belediye başvuru yönetiminden bağımsız platform inceleme alanı.</p></div><div className="panel p-5 text-sm leading-6">Başvuru sahibinin beyanını tek başına doğrulama saymayın. Bağımsız kurumsal kaynaktan temsil yetkisini teyit edin; mükerrer işletme, hizmet kapsamı ve yayımlanacak kişisel bilgileri kontrol edin. Onay bir kalite garantisi değildir. Kendi kaydınızı onaylayamazsınız.</div><div className="flex flex-wrap gap-3"><label className="field flex-1 max-w-sm">İnceleme durumu<select value={status} onChange={e=>{setStatus(e.target.value);setPage(1);setNotice('');}}>{['PENDING','PUBLISHED','CHANGES_REQUESTED','SUSPENDED'].map(s=><option key={s} value={s}>{BUSINESS_STATUSES[s]}</option>)}</select></label><button className="btn-light self-end" onClick={()=>void load()}>Listeyi yenile</button></div><ErrorBox message={error}/>{notice&&<p role="status" className="bg-accent text-accent-foreground rounded-lg p-3 text-sm">{notice}</p>}{loading?<Loading/>:items.length?<div className="space-y-5">{items.map(item=><ReviewCard key={`${item.id}-${item.revision}`} item={item} onSaved={async()=>{setNotice('İnceleme kararı ve işlem geçmişi kaydedildi.');await load();}}/>)}</div>:<p className="panel p-8 text-center text-muted-foreground">Bu durumda işletme kaydı bulunmuyor.</p>}<div className="flex items-center gap-3"><button className="btn-light" disabled={loading||page===1} onClick={()=>setPage(p=>p-1)}>Önceki</button><span className="text-sm">Sayfa {page}</span><button className="btn-light" disabled={loading||!hasNext} onClick={()=>setPage(p=>p+1)}>Sonraki</button></div></div>;
}
function ReviewCard({item,onSaved}:{item:ReviewBusiness;onSaved:()=>Promise<void>}){
 const [message,setMessage]=useState(''),[method,setMethod]=useState(''),[confirmed,setConfirmed]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function decide(action:string){setBusy(true);setError('');try{await request(`/api/platform/businesses/${item.id}`,{method:'PATCH',...jsonBody({action,revision:item.revision,message,method:method||undefined,confirmed})});await onSaved();}catch(e){console.error(e);setError(e instanceof Error?e.message:'İşlem tamamlanamadı.');}finally{setBusy(false);}}
 return <section className="panel p-5 md:p-6 space-y-4"><div><span className="status bg-accent text-accent-foreground">{BUSINESS_STATUSES[item.status]}</span><h2 className="section-title mt-3">{item.name} · {item.branchName}</h2><p className="text-sm text-muted-foreground mt-1">{BUSINESS_CATEGORIES[item.category]} · {item.district}</p></div><dl className="grid sm:grid-cols-2 gap-4 text-sm">{[['Tanıtım',item.description],['Hizmetler',item.services],['Kapsam dışı',item.exclusions||'Belirtilmedi'],['Hizmet bölgeleri',item.serviceDistricts.join(', ')],['Herkese açık adres',item.publicAddress||'Belirtilmedi'],['Herkese açık telefon',item.publicPhone||'Belirtilmedi'],['İnternet sitesi',item.website||'Belirtilmedi'],['Çalışma saatleri',item.hoursText||'Belirtilmedi']].map(([k,v])=><div key={k} className="break-words"><dt className="text-muted-foreground mb-1">{k}</dt><dd className="whitespace-pre-wrap" suppressHydrationWarning>{v}</dd></div>)}</dl><div className="rounded-lg bg-muted p-4 space-y-2 text-sm"><h3 className="font-semibold">Özel inceleme bilgileri</h3><p>Başvuran: {item.user.name} · <span suppressHydrationWarning>{item.user.email}</span></p><p>İletişim: <span suppressHydrationWarning>{item.verificationContact}</span></p><p className="whitespace-pre-wrap">Yetki beyanı: {item.ownershipStatement}</p></div><details className="text-sm"><summary className="cursor-pointer">İşlem geçmişi</summary><ul className="mt-2 space-y-2">{item.events.map(e=><li key={e.id}><SafeDate date={e.createdAt} locale="tr-TR" options={{dateStyle:'short'}}/> · {e.message}</li>)}</ul></details><ErrorBox message={error}/><label className="field">İnceleme notu / düzeltme gerekçesi *<textarea rows={3} minLength={15} maxLength={1000} value={message} onChange={e=>setMessage(e.target.value)} placeholder="Yaptığınız kontrolü veya gerekli düzeltmeyi açıklayın. Kişisel belge bilgisi yazmayın."/><span className="text-xs text-muted-foreground">En az 15 karakter. İşletme sahibi bu notu görebilir.</span></label>{item.status==='PENDING'&&<><label className="field">Sahiplik kontrol yöntemi<select value={method} onChange={e=>setMethod(e.target.value)}><option value="">Yöntem seçin</option>{Object.entries(VERIFICATION_METHODS).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label className="flex items-start gap-3 text-sm"><input type="checkbox" className="!w-4 !h-4 shrink-0" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>Bağımsız kaynaktan temsil yetkisini, profil içeriğini ve mükerrer kayıt durumunu kontrol ettim.</label></>}<div className="flex flex-wrap gap-3">{item.status==='PENDING'&&<button className="btn" disabled={busy||message.trim().length<15||!method||!confirmed} onClick={()=>void decide('approve')}>Sahipliği onayla ve yayımla</button>}{['PENDING','SUSPENDED','PUBLISHED'].includes(item.status)&&<button className="btn-light" disabled={busy||message.trim().length<15} onClick={()=>void decide('changes')}>Düzeltme iste / yayından kaldır</button>}{item.status==='PUBLISHED'&&<button className="btn-light text-destructive" disabled={busy||message.trim().length<15} onClick={()=>void decide('suspend')}>Yayını durdur</button>}</div></section>;
}
